using DroidLab.Devices;
using System.Windows;
using System.Windows.Controls;
namespace DroidLab.Desktop;
public partial class MainWindow : Window {
 private static readonly string[] Modules = ["Command Center","Device Intelligence","Diagnostics Lab","Troubleshooting Lab","ADB Workbench","Fastboot Lab","Firmware & Flashing","Recovery Center","Backup & Restoration","Technician Center","SIM & Network Lab","Security & CVE Lab","Application Manager","File & Storage Lab","Connectivity Lab","Reporting Center"];
 public MainWindow(){InitializeComponent(); Navigation.ItemsSource=Modules; DiagnosticPicker.ItemsSource=Enum.GetValues<DiagnosticKind>();DiagnosticPicker.SelectedIndex=0;Navigation.SelectedIndex=0;}
 private void Navigate(object sender, SelectionChangedEventArgs e){if(Navigation.SelectedItem is not string name)return; Heading.Text=name; bool ready=name=="Command Center"||name=="ADB Workbench"||name=="Fastboot Lab"||name=="Device Intelligence"||name=="Diagnostics Lab"||name=="Application Manager"||name=="File & Storage Lab"; Description.Text=ready?"Read-only ADB and Fastboot discovery. Connect an authorized device with USB debugging enabled.":"Planned module — not implemented in this foundation build."; Scan.Visibility=Output.Visibility=DiagnosticPanel.Visibility=ready?Visibility.Visible:Visibility.Collapsed;}
 private async void Detect(object sender,RoutedEventArgs e){Scan.IsEnabled=false;Output.Text="Detecting devices...";try{var results=await Task.WhenAll(Discovery.ScanAsync("ADB"),Discovery.ScanAsync("Fastboot"));DevicePicker.ItemsSource=results.SelectMany(r=>r.Devices).Where(d=>d.Transport=="ADB"&&d.State=="device").ToList();DevicePicker.SelectedIndex=0;Output.Text=string.Join("\n\n",results.Select(r=>r.Transport+": "+(r.Error??(r.Devices.Count==0?"No devices":string.Join("\n",r.Devices.Select(d=>$"{d.Serial} | {d.State} | {d.Details}"))))));}catch(Exception ex){Output.Text=ex.Message;}finally{Scan.IsEnabled=true;}}
 private async void ReadDiagnostic(object sender,RoutedEventArgs e){if(DevicePicker.SelectedItem is not Device device||DiagnosticPicker.SelectedItem is not DiagnosticKind kind){Output.Text="Select an authorized device after discovery.";return;}ReadButton.IsEnabled=false;try{Output.Text=await Diagnostics.ReadAsync(device,kind);}catch(Exception ex){Output.Text=ex.Message;}finally{ReadButton.IsEnabled=true;}}
}